/** Mango resource services share one transport. Writes are never retried automatically. */
export class Mango {
  readonly agents: AgentsResource;
  readonly deploymentRuns: DeploymentRunsResource;
  readonly deployments: DeploymentsResource;
  readonly environments: EnvironmentsResource;
  readonly files: FilesResource;
  readonly memoryStores: MemoryStoresResource;
  readonly sessions: SessionsResource;
  readonly skills: SkillsResource;
  readonly system: SystemResource;
  readonly vaults: VaultsResource;
  readonly webhooks: WebhooksResource;
  constructor(options: ClientOptions) {
    const transport = new Transport(options);
    this.agents = new AgentsResource(transport);
    this.deploymentRuns = new DeploymentRunsResource(transport);
    this.deployments = new DeploymentsResource(transport);
    this.environments = new EnvironmentsResource(transport);
    this.files = new FilesResource(transport);
    this.memoryStores = new MemoryStoresResource(transport);
    this.sessions = new SessionsResource(transport);
    this.skills = new SkillsResource(transport);
    this.system = new SystemResource(transport);
    this.vaults = new VaultsResource(transport);
    this.webhooks = new WebhooksResource(transport);
  }
}

export class AgentsResource {
  readonly versions: AgentsVersionsResource;
  constructor(private readonly transport: Transport) {
    this.versions = new AgentsVersionsResource(transport);
  }

  /** Archive an Agent */
  archive(agent_id: string, options: RequestOptions = {}): Promise<ArchiveAgentResponse> {
    return this.transport.request<ArchiveAgentResponse>(operations.archiveAgent, { "agent_id": agent_id }, options);
  }

  /** Create an Agent */
  create(params: CreateAgentParams, options: RequestOptions = {}): Promise<CreateAgentResponse> {
    return this.transport.request<CreateAgentResponse>(operations.createAgent, { body: { "description": params.description, "mcp_servers": params.mcp_servers, "metadata": params.metadata, "model": params.model, "multiagent": params.multiagent, "name": params.name, "skills": params.skills, "system": params.system, "tools": params.tools } }, options);
  }

  /** Get an Agent */
  retrieve(agent_id: string, options: RequestOptions = {}): Promise<GetAgentResponse> {
    return this.transport.request<GetAgentResponse>(operations.getAgent, { "agent_id": agent_id }, options);
  }

  /** List Agents */
  list(params: ListAgentsParams = {}, options: RequestOptions = {}): Promise<ListAgentsResponse> {
    return this.transport.request<ListAgentsResponse>(operations.listAgents, { "limit": params.limit, "page": params.page, "include_archived": params.include_archived, "created_at[gte]": params.created_at_gte, "created_at[lte]": params.created_at_lte }, options);
  }

  /** Lazily fetch pages; stopping iteration prevents further requests. */
  listPages(params: ListAgentsParams = {}, options: RequestOptions = {}): AsyncGenerator<ListAgentsResponse> {
    return this.transport.pages<ListAgentsResponse>(operations.listAgents, { "limit": params.limit, "page": params.page, "include_archived": params.include_archived, "created_at[gte]": params.created_at_gte, "created_at[lte]": params.created_at_lte }, options);
  }

  /** Lazily traverse all items using the API's opaque cursor. */
  async *listItems(params: ListAgentsParams = {}, options: RequestOptions = {}): AsyncGenerator<Agent> {
    for await (const page of this.listPages(params, options)) yield* page.data;
  }

  /** Update an Agent and create a new version when fields change */
  update(agent_id: string, params: UpdateAgentParams = {}, options: RequestOptions = {}): Promise<UpdateAgentResponse> {
    return this.transport.request<UpdateAgentResponse>(operations.updateAgent, { "agent_id": agent_id, body: { "description": params.description, "mcp_servers": params.mcp_servers, "metadata": params.metadata, "model": params.model, "multiagent": params.multiagent, "name": params.name, "skills": params.skills, "system": params.system, "tools": params.tools, "version": params.version } }, options);
  }

}

